// Build a Telegram alert about the failed workflow
const j = $input.first().json;
const ex = j.execution || {}, wf = j.workflow || {}, tr = j.trigger || {};
const err = ex.error || tr.error || {};
const raw = String(err.message || err.description || 'Noma\'lum xato');
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// Plain-language hints for the most common errors
let izoh = '';
if (/too many requests|429/i.test(raw)) izoh = "iBox so'rovlar limitiga yetdi. Biroz kutib, qayta ishga tushiring.";
else if (/service unavailable|503|502|504|gateway/i.test(raw)) izoh = 'iBox serveri vaqtincha band yoki ishlamayapti.';
else if (/401|unauthori|token\.invalid|bad\.filial/i.test(raw)) izoh = "iBox kaliti (token) yoki filial raqami noto'g'ri / muddati o'tgan.";
else if (/timeout|ETIMEDOUT|ECONNRESET|socket hang up/i.test(raw)) izoh = "iBox javob bermadi (aloqa uzildi yoki juda sekin).";
else if (/chat not found|bot was blocked|not enough rights|403.*telegram/i.test(raw)) izoh = "Telegram: bot kanalga yoza olmadi (admin emas yoki kanal ID noto'g'ri).";
else if (/message is too long/i.test(raw)) izoh = 'Telegram: xabar juda uzun.';

const TZ = 5 * 3600 * 1000;
const d = new Date(Date.now() + TZ);
const p = n => String(n).padStart(2, '0');
const vaqt = `${p(d.getUTCDate())}.${p(d.getUTCMonth() + 1)}.${d.getUTCFullYear()} ${p(d.getUTCHours())}:${p(d.getUTCMinutes())}`;

let t = `⚠️ <b>HISOBOT YUBORILMADI</b>\n\n`;
t += `📋 <b>${esc(wf.name || 'Workflow')}</b>\n`;
t += `🕐 ${vaqt}\n`;
if (ex.lastNodeExecuted) t += `🧩 Xato bloki: <b>${esc(ex.lastNodeExecuted)}</b>\n`;
t += `❌ ${esc(raw.slice(0, 300))}\n`;
if (izoh) t += `\n💡 ${izoh}\n`;
if (ex.url) t += `\n<a href="${esc(ex.url)}">n8n'da ochish</a>`;
return [{ json: { text: t } }];
